      *   minPriceMinor: ?int,
      *   maxPriceMinor: ?int,
      *   sort: string
      * } $filters
      * @return array{products: list<array<string, mixed>>, total: int}
      */
     public function listCatalog(array $filters, ?array $productIds = null): array
     {
         if ($productIds === []) {
