             >
               {result.offers.length > 0 ? (
                 <ol className="space-y-3">
                   {result.offers.map((offer) => {
                     const selected = selectedOffer?.offerId === offer.offerId
                     const compareAtPrice =
                       offer.compareAtPriceMinor !== null &&
