             $cartId = $this->carts->cartId($userId);
             $item = $cartId === null ? null : $this->carts->item($cartId, $itemId, true);
             if ($item === null) {
                 throw new ApiException(404, 'CART_ITEM_NOT_FOUND', 'The cart item was not found.');
