         } catch (JsonException) {
             throw new ApiException(400, 'INVALID_JSON', 'The request body must be valid JSON.');
         }

         if (!$body instanceof stdClass) {
             throw new ApiException(400, 'INVALID_JSON', 'The request body must be a JSON object.');
         }

