   useEffect,
   useMemo,
   useState,
   type ReactNode,
 } from 'react'
 import { ApiError } from '../lib/api/client'
 import {
   getCsrfToken,
   getCurrentUser,
   login as requestLogin,
   logout as requestLogout,
   register as requestRegister,
   type AuthUser,
 } from '../lib/api/auth'
 import {
   addCartItem,
   getCart,
   removeCartItem as requestRemoveCartItem,
   updateCartItem as requestUpdateCartItem,
 } from '../lib/api/cart'

 interface AuthContextValue {
   user: AuthUser | null
   loading: boolean
   error: string | null
   cartItemCount: number
   login: (input: { email: string; password: string }) => Promise<void>
   register: (input: {
     email: string
     password: string
     displayName: string
   }) => Promise<void>
   logout: () => Promise<void>
   addToCart: (offerId: number) => Promise<void>
   updateCartQuantity: (itemId: number, quantity: number) => Promise<void>
   removeFromCart: (itemId: number) => Promise<void>
   refreshCart: () => Promise<void>
 }

 const AuthContext = createContext<AuthContextValue | null>(null)

 function AuthProvider({ children }: { children: ReactNode }) {
   const [user, setUser] = useState<AuthUser | null>(null)
   const [csrfToken, setCsrfToken] = useState<string | null>(null)
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState<string | null>(null)
   const [cartItemCount, setCartItemCount] = useState(0)

   const refreshCart = useCallback(async () => {
     const cart = await getCart()
     setCartItemCount(cart.itemCount)
   }, [])

   useEffect(() => {
     let active = true

     async function initialize(): Promise<void> {
       try {
         const token = await getCsrfToken()
         if (!active) return
         setCsrfToken(token)

         try {
           const currentUser = await getCurrentUser()
           if (!active) return
           setUser(currentUser)
           const cart = await getCart()
           if (active) setCartItemCount(cart.itemCount)
         } catch (cause) {
           if (cause instanceof ApiError && cause.status === 401) {
             if (active) {
               setUser(null)
               setCartItemCount(0)
             }
           } else {
             throw cause
           }
         }
       } catch (cause) {
         if (active) {
           setError(
             cause instanceof Error
               ? cause.message
               : 'Your account could not be loaded. Please refresh the page.',
           )
         }
       } finally {
         if (active) setLoading(false)
       }
     }

     void initialize()
     return () => {
       active = false
     }
   }, [])

   const login = useCallback(
     async (input: { email: string; password: string }) => {
       const token = csrfToken ?? (await getCsrfToken())
       const result = await requestLogin(input, token)
       setCsrfToken(result.csrfToken)
       setUser(result.user)
       try {
         const cart = await getCart()
         setCartItemCount(cart.itemCount)
       } catch (cause) {
         setError(
           cause instanceof Error
             ? `Signed in, but the cart could not be loaded: ${cause.message}`
             : 'Signed in, but the cart could not be loaded.',
         )
       }
     },
     [csrfToken],
   )

   const register = useCallback(
     async (input: { email: string; password: string; displayName: string }) => {
       const token = csrfToken ?? (await getCsrfToken())
       const result = await requestRegister(input, token)
       setCsrfToken(result.csrfToken)
       setUser(result.user)
       try {
         const cart = await getCart()
         setCartItemCount(cart.itemCount)
       } catch (cause) {
         setError(
           cause instanceof Error
             ? `Account created, but the cart could not be loaded: ${cause.message}`
             : 'Account created, but the cart could not be loaded.',
         )
       }
     },
     [csrfToken],
   )

   const logout = useCallback(async () => {
     const token = csrfToken ?? (await getCsrfToken())
     await requestLogout(token)
     setUser(null)
     setCsrfToken(null)
     setCartItemCount(0)
   }, [csrfToken])

   const addToCart = useCallback(
     async (offerId: number) => {
       if (user === null) {
         throw new ApiError('Sign in to add items to your cart.', 401, 'UNAUTHENTICATED')
       }
       const token = csrfToken ?? (await getCsrfToken())
       const cart = await addCartItem(offerId, 1, token)
       setCartItemCount(cart.itemCount)
     },
     [csrfToken, user],
   )

   const updateCartQuantity = useCallback(
     async (itemId: number, quantity: number) => {
       if (user === null) {
         throw new ApiError('Sign in to update your cart.', 401, 'UNAUTHENTICATED')
       }
       const token = csrfToken ?? (await getCsrfToken())
       const cart = await requestUpdateCartItem(itemId, quantity, token)
       setCartItemCount(cart.itemCount)
     },
     [csrfToken, user],
   )

   const removeFromCart = useCallback(
     async (itemId: number) => {
       if (user === null) {
         throw new ApiError('Sign in to update your cart.', 401, 'UNAUTHENTICATED')
       }
       const token = csrfToken ?? (await getCsrfToken())
       await requestRemoveCartItem(itemId, token)
       await refreshCart()
     },
     [csrfToken, refreshCart, user],
   )

   const value = useMemo(
     () => ({
       user,
       loading,
       error,
       cartItemCount,
       login,
       register,
       logout,
       addToCart,
       updateCartQuantity,
       removeFromCart,
       refreshCart,
     }),
     [
       user,
       loading,
       error,
       cartItemCount,
       login,
       register,
       logout,
       addToCart,
       updateCartQuantity,
       removeFromCart,
       refreshCart,
     ],
   )

   return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
 }

 function useAuth(): AuthContextValue {
   const context = useContext(AuthContext)
   if (context === null) {
     throw new Error('useAuth must be used within AuthProvider.')
   }
   return context
 }

