 import {
   getCsrfToken,
   getCurrentUser,
   login as requestLogin,
   logout as requestLogout,
   register as requestRegister,
   type AuthUser,
 } from '../lib/api/auth'
 import {
   addCartItem,
   getCart,
   removeCartItem as requestRemoveCartItem,
   updateCartItem as requestUpdateCartItem,
 } from '../lib/api/cart'
 import { AuthContext, type AuthContextValue } from './auth-context'

 function AuthProvider({ children }: { children: ReactNode }) {
   const [user, setUser] = useState<AuthUser | null>(null)
   const [csrfToken, setCsrfToken] = useState<string | null>(null)
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState<string | null>(null)
   const [cartItemCount, setCartItemCount] = useState(0)

   const refreshCart = useCallback(async () => {
     const cart = await getCart()
     setCartItemCount(cart.itemCount)
   }, [])

   useEffect(() => {
     let active = true

     async function initialize(): Promise<void> {
       try {
         const token = await getCsrfToken()
         if (!active) return
         setCsrfToken(token)

         try {
           const currentUser = await getCurrentUser()
           if (!active) return
           setUser(currentUser)
           const cart = await getCart()
           if (active) setCartItemCount(cart.itemCount)
         } catch (cause) {
           if (cause instanceof ApiError && cause.status === 401) {
             if (active) {
               setUser(null)
               setCartItemCount(0)
             }
           } else {
             throw cause
           }
         }
       } catch (cause) {
         if (active) {
           setError(
             cause instanceof Error
               ? cause.message
               : 'Your account could not be loaded. Please refresh the page.',
           )
         }
       } finally {
         if (active) setLoading(false)
       }
     }

     void initialize()
     return () => {
       active = false
     }
   }, [])

   const login = useCallback(
     async (input: { email: string; password: string }) => {
       const token = csrfToken ?? (await getCsrfToken())
       const result = await requestLogin(input, token)
       setCsrfToken(result.csrfToken)
       setUser(result.user)
       try {
         const cart = await getCart()
         setCartItemCount(cart.itemCount)
       } catch (cause) {
         setError(
           cause instanceof Error
             ? `Signed in, but the cart could not be loaded: ${cause.message}`
             : 'Signed in, but the cart could not be loaded.',
         )
       }
     },
     [csrfToken],
   )

   const register = useCallback(
     async (input: { email: string; password: string; displayName: string }) => {
       const token = csrfToken ?? (await getCsrfToken())
       const result = await requestRegister(input, token)
       setCsrfToken(result.csrfToken)
       setUser(result.user)
       try {
         const cart = await getCart()
         setCartItemCount(cart.itemCount)
       } catch (cause) {
         setError(
           cause instanceof Error
             ? `Account created, but the cart could not be loaded: ${cause.message}`
             : 'Account created, but the cart could not be loaded.',
         )
       }
     },
     [csrfToken],
   )

