                         $item['productName'],
                         $item['sellerName'],
                         $item['platformName'],
                         $item['regionName'],
                         $item['quantity'],
                         $item['priceMinor'],
                         $currency,
                     );
                     $this->orders->assignKeys($item['keyIds'], $orderItemId);
                 }

