php -r '
$path = getcwd() . "/.env";
$contents = file_get_contents($path);
if ($contents === false) { throw new RuntimeException("Could not read root .env."); }
$names = ["KEY_ENCRYPTION_KEYS", "KEY_ENCRYPTION_KEY_VERSION"];
foreach ($names as $name) {
    if (preg_match("/^\\s*" . preg_quote($name, "/") . "\\s*=/m", $contents) === 1) {
        throw new RuntimeException($name . " is already assigned; refusing to overwrite it.");
    }
}
$key = base64_encode(random_bytes(32));
$json = json_encode(["1" => $key], JSON_THROW_ON_ERROR);
$separator = $contents === "" || str_ends_with($contents, "\n") ? "" : PHP_EOL;
$addition = $separator . "KEY_ENCRYPTION_KEYS='" . $json . "'" . PHP_EOL . "KEY_ENCRYPTION_KEY_VERSION=1" . PHP_EOL;
if (file_put_contents($path, $addition, FILE_APPEND | LOCK_EX) === false) {
    throw new RuntimeException("Could not append encryption settings to root .env.");
}
if (!chmod($path, 0600)) {
