     `orders:detail:${orderId}`,
     (signal) => getOrder(orderId, signal),
     user !== null && isValidId,
   )
   const [deliveredKeys, setDeliveredKeys] = useState<{
     orderId: string
     data: OrderKeys
   } | null>(null)
   const [deliveryError, setDeliveryError] = useState<{
     orderId: string
     message: string
